// TH15 v1.00b Extra Stage 道中第 8 波 —— GirlD03 八只对称编队
// 源: st07.ecl.txt:1253-1272 (MainSub06)、767-793 (GirlD03)、795-818 (GirlD03_at)
// 卡帧 0 = MainSub06 入口；源无硬时限，2100 帧为本波排程 + 尾弹的合成窗口估计。
// 本卡只交付 Extra（源 O 位，目标 rank4），不混用 Lunatic 数值。

const TIME_LIMIT: int = 2224;   // 120 开场缓冲 + 2100 窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;

const TH15_OVAL: int = 672;     // 源 etSprite(0, 20, 3): type20 -> TH15_OVAL
const TH15_OVAL_COLOR: int = 3;

// GirlD03_at（795-818）：wait(60) 后每 20 帧发一轮固定方向整周环，
// 环基角 %A 每轮减去 pi/I0；I0=28（前四只）或 24（后四只）。
async sub girl_fire(n: int) {
    wait(60);                                  // 0798 wait(60)
    sh_reset(0);                               // 0799 etNew(0)
    sh_sprite(0, TH15_OVAL, TH15_OVAL_COLOR);  // 0801 etSprite(0,20,3)
    sh_ring(0, 1);                             // 0800 etAim(0,3) 固定方向整周环
    sh_aim(0, 0);
    sh_count(0, n, 1);                         // 0802 etCount(0,$I0,1)
    sh_speed(0, 2fx, 0fx);                     // 0804 etSpeed(0,2.0,0.2), 1 层只取 2.0
    // 0806 etDist(0,24) 与出生 ANIM a=1 的 position -= 4*velocity 合成：
    // 24 - 4*2.0 = 16px 净出生距离（出生阶段本身按已批准口径省略）。
    sh_dist(0, 16fx);

    var a0: int = rand(65536) - 32768;         // 0807 %A = %RANDRAD: [-pi,pi)
    // 0810-0816 循环：1000 轮，每轮 etAngle(A)、etOn、A -= pi/n、wait(20)。
    // 累计角用 k*32768/n 直接算，避免逐轮截断误差累积。
    for k in 0..1000 {
        var a: int = a0 - (k * 32768) / n;
        sh_angle(0, a as angle, 0deg);         // 0811 etAngle(0,%A,0)
        sh_fire(0);                            // 0812 etOn(0)
        wait(20);                              // 0814 wait(20)
    }
}

// GirlD03 主任务（767-793）。mirror = 1 对应 enmCreateM 的子镜像初值。
// 源普通 moveVel/moveSpeedTime 在镜像敌人上写 x 分量取负：角度 theta -> pi-theta。
async sub girl_main(n: int, mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);                         // 0776 setHurtbox(32,32): 32*0.5
    set_hitbox(12fx);                          // 0777 setHitbox(24,24): 24*0.5

    // 0778-0779 moveVel(1.5707964,4.7) 后 moveSpeedTime(60,1,0)
    move_vel(0, 16384bam, 4.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);

    spawn girl_fire(n);                        // 0780 @GirlD03_at() async

    wait(60);                                  // 0781 +60 时间标签
    // 0782-0783 moveVel(2.9452431,0) 后 moveSpeedTime(60,1,0.5)
    var drift: angle = 30720bam;               // 2.9452431 rad = 168.75deg
    if mirror != 0 { drift = 2048bam; }        // pi - 2.9452431 = 11.25deg
    move_vel(0, drift, 0fx, EASE_LINEAR);
    move_speed(60, 0.5fx, EASE_QUAD_IN);

    wait(600);                                 // 0784 wait(600)
    move_speed(80, 1fx, EASE_QUAD_IN);         // 0785 moveSpeedTime(80,1,1.0)
    wait(60);                                  // 0786 wait(60)
    // 0787-0791 goto GirlD03_492/GirlD03_472 的 wait(1000) 循环不含后续行为，
    // 只保持速度 1.0 的漂移与敌存活。
    loop { wait(1000); }
}

// MainSub06（1253-1272）：顺序与间隔照源；I0 按组传入（28 x4，24 x4）。
// enmCreate 的 RANDF2*32+64 逐只抽样；enmCreateM 一侧取 -64 并带子镜像。
async sub pattern() {
    wait(OPENING_BUFFER);                      // 开场 120 帧后开始源攻击
    // 本卡只有 Extra(rank4)；保留一次 rank 读取，其他 rank 不进入本波。
    if global(GVAR_RANK) != 4 { loop { wait(1); } }

    // 1255-1256 $I0=28; enmCreate(+64)
    var x: fx = (rand(65536) - 32768) as fx / 32768 * 32fx + 64fx;
    _ = spawn_enemy(x, -48fx, 2000, 0, 1000, 0, girl_main(28, 0));
    wait(180);                                 // 1257
    // 1258 enmCreateM(-64)
    x = (rand(65536) - 32768) as fx / 32768 * 32fx - 64fx;
    _ = spawn_enemy(x, -48fx, 2000, 0, 1000, 0, girl_main(28, 1));
    wait(180);                                 // 1259
    // 1260 enmCreate(+64)
    x = (rand(65536) - 32768) as fx / 32768 * 32fx + 64fx;
    _ = spawn_enemy(x, -48fx, 2000, 0, 1000, 0, girl_main(28, 0));
    wait(180);                                 // 1261
    // 1262 enmCreateM(-64)
    x = (rand(65536) - 32768) as fx / 32768 * 32fx - 64fx;
    _ = spawn_enemy(x, -48fx, 2000, 0, 1000, 0, girl_main(28, 1));
    wait(240);                                 // 1263

    // 1264 $I0=24；1265-1266 同时创建 +32(M) 与 -32。
    _ = spawn_enemy(32fx, -48fx, 1500, 0, 1000, 0, girl_main(24, 1));
    _ = spawn_enemy(-32fx, -48fx, 1500, 0, 1000, 0, girl_main(24, 0));
    wait(240);                                 // 1267
    // 1268-1269 同时创建 -160(M) 与 +160。
    _ = spawn_enemy(-160fx, -48fx, 1500, 0, 1000, 0, girl_main(24, 1));
    _ = spawn_enemy(160fx, -48fx, 1500, 0, 1000, 0, girl_main(24, 0));
    wait(20);                                  // 1270
    return;                                    // 1271
}

// 独立无敌外壳：control 只承载段事件，放在 (0,0) 且关闭体碰。
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
